#!/bin/bash
# Writes the license files shipped in every installer into <out-dir>:
# ZMark's own licenses, the Lucide icon license and THIRD-PARTY-NOTICES.html
# generated by cargo-about from Cargo.lock (config: about.toml).
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="${1:?usage: $0 <out-dir>}"

if ! cargo about --version >/dev/null 2>&1; then
    echo "error: cargo-about is required (brew install cargo-about, or cargo install --locked cargo-about)" >&2
    exit 1
fi

mkdir -p "$OUT"
cp "$ROOT/LICENSE-MIT" "$ROOT/LICENSE-APACHE" "$ROOT/crates/zmark_app/assets/icons/LICENSE-LUCIDE" "$OUT/"
NOTICES="$OUT/THIRD-PARTY-NOTICES.html"
# cargo about takes ~20 s; skip it while Cargo.lock and the config are unchanged.
if [ -s "$NOTICES" ] && [ "$NOTICES" -nt "$ROOT/Cargo.lock" ] && [ "$NOTICES" -nt "$ROOT/about.toml" ] \
    && [ "$NOTICES" -nt "$ROOT/packaging/licenses/about.hbs" ]; then
    exit 0
fi
cargo about generate --locked --manifest-path "$ROOT/Cargo.toml" -c "$ROOT/about.toml" \
    -o "$NOTICES.tmp" "$ROOT/packaging/licenses/about.hbs"
mv "$NOTICES.tmp" "$NOTICES"
